// ─── File: OutboxTransferDemo.java ───
// Runnable demo: naive dual-write (loses event on crash) vs transactional outbox.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class OutboxTransferDemo {

    private static final Logger log = Logger.getLogger("outbox");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("===== NAIVE DUAL-WRITE: crash after DB commit loses the event =====");
        NotificationConsumer naiveConsumer = new NotificationConsumer();
        NaiveDualWriteService naive = new NaiveDualWriteService(naiveConsumer);
        naive.transfer("SAV2001", "CUR3001", new BigDecimal("50000"), /*crashBeforePublish*/ true);
        log.severe("[NAIVE] money moved but NO event published — consumers never learned");

        log.info("===== TRANSACTIONAL OUTBOX: event survives the crash =====");
        OutboxRepository outbox = new OutboxRepository();
        TransferService svc = new TransferService(outbox);
        svc.transfer("SAV2001", "CUR3001", new BigDecimal("50000"), /*crashAfterCommit*/ true);
        log.info("[OUTBOX] crashed after commit — but outbox row is safely persisted");

        // After restart, the relay publishes the outbox row (at-least-once).
        NotificationConsumer consumer = new NotificationConsumer();
        OutboxRelay relay = new OutboxRelay(outbox, consumer);
        relay.drain();   // publishes
        relay.drain();   // re-publishes same row → consumer dedupes
    }
}

// ─── model/Account.java ───
class Account {
    final String id; BigDecimal balance;
    Account(String id, BigDecimal balance) { this.id = id; this.balance = balance; }
}

// ─── model/OutboxRow.java ───
class OutboxRow {
    final String eventId; final String aggregate; final String type; final String payload;
    boolean published = false;
    OutboxRow(String eventId, String aggregate, String type, String payload) {
        this.eventId = eventId; this.aggregate = aggregate; this.type = type; this.payload = payload;
    }
}

// ─── service/NaiveDualWriteService.java — the WRONG way ───
class NaiveDualWriteService {
    private static final Logger log = Logger.getLogger("outbox");
    private final Map<String, Account> db = new HashMap<>();
    private final NotificationConsumer broker;
    NaiveDualWriteService(NotificationConsumer broker) {
        db.put("SAV2001", new Account("SAV2001", new BigDecimal("1000000")));
        db.put("CUR3001", new Account("CUR3001", new BigDecimal("250000")));
        this.broker = broker;
    }
    void transfer(String from, String to, BigDecimal amt, boolean crashBeforePublish) {
        // Write #1: commit the DB change.
        db.get(from).balance = db.get(from).balance.subtract(amt);
        db.get(to).balance = db.get(to).balance.add(amt);
        log.info(() -> "[NAIVE] DB committed: " + from + "=Rs." + db.get(from).balance);
        if (crashBeforePublish) return;   // crash BEFORE write #2 → event lost forever
        // Write #2: publish to Kafka (never reached when crashed).
        broker.onEvent(new OutboxRow("EVT-X", from, "TransferCompleted", from + "->" + to + ":" + amt));
    }
}

// ─── service/TransferService.java — the RIGHT way (outbox) ───
class TransferService {
    private static final Logger log = Logger.getLogger("outbox");
    private final Map<String, Account> db = new HashMap<>();
    private final OutboxRepository outbox;
    TransferService(OutboxRepository outbox) {
        db.put("SAV2001", new Account("SAV2001", new BigDecimal("1000000")));
        db.put("CUR3001", new Account("CUR3001", new BigDecimal("250000")));
        this.outbox = outbox;
    }
    // One local transaction: balance change + outbox insert commit together.
    void transfer(String from, String to, BigDecimal amt, boolean crashAfterCommit) {
        String eventId = "EVT-" + UUID.randomUUID().toString().substring(0, 8);
        // BEGIN TX
        db.get(from).balance = db.get(from).balance.subtract(amt);
        db.get(to).balance = db.get(to).balance.add(amt);
        outbox.insert(new OutboxRow(eventId, from, "TransferCompleted", from + "->" + to + ":" + amt));
        // COMMIT (both rows persisted atomically)
        log.info(() -> "[OUTBOX] committed balance + outbox row in ONE txn (event_id=" + eventId + ")");
        if (crashAfterCommit) return;   // crash now — relay will still publish the row later
    }
}

// ─── outbox/OutboxRepository.java ───
class OutboxRepository {
    final List<OutboxRow> rows = new ArrayList<>();
    void insert(OutboxRow row) { rows.add(row); }
    List<OutboxRow> findUnpublished() {
        List<OutboxRow> out = new ArrayList<>();
        for (OutboxRow r : rows) if (!r.published) out.add(r);
        return out;
    }
}

// ─── outbox/OutboxRelay.java — polling relay (CDC is the prod alternative) ───
class OutboxRelay {
    private static final Logger log = Logger.getLogger("outbox");
    private final OutboxRepository outbox; private final NotificationConsumer consumer;
    OutboxRelay(OutboxRepository outbox, NotificationConsumer consumer) { this.outbox = outbox; this.consumer = consumer; }
    void drain() {
        for (OutboxRow r : outbox.findUnpublished()) {
            log.fine(() -> "[RELAY] publishing " + r.eventId + " to Kafka");
            consumer.onEvent(r);     // at-least-once: may crash before marking published
            r.published = true;
        }
    }
}

// ─── consumer/NotificationConsumer.java — idempotent ───
class NotificationConsumer {
    private static final Logger log = Logger.getLogger("outbox");
    private final Set<String> processed = new HashSet<>();
    void onEvent(OutboxRow e) {
        if (!processed.add(e.eventId)) {
            log.fine(() -> "[NOTIFY] duplicate " + e.eventId + " ignored (idempotent)");
            return;
        }
        log.info(() -> "[NOTIFY] SMS for " + e.type + " " + e.payload);
    }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
